insert into automation_services (name, slug, summary, description, features, industries, pricing_type, featured, status) values ('AI Customer Service Agent', 'ai-customer-service-agent', 'A 24/7 AI agent that answers customer questions, takes orders and escalates when needed.', 'Deployed across WhatsApp, Instagram and your website, the AI Customer Service Agent understands your product catalogue, answers repetitive questions instantly, and hands off to a human teammate the moment a conversation needs one.', ARRAY['24/7 multi-channel coverage', 'Trained on your own knowledge base', 'Order capture and status updates', 'Human hand-off with full conversation context'], ARRAY['Food & Restaurants', 'Retail', 'Services'], 'Monthly Retainer', true, 'Published') on conflict (slug) do nothing;
insert into automation_services (name, slug, summary, description, features, industries, pricing_type, featured, status) values ('AI Sales Assistant', 'ai-sales-assistant', 'Qualifies inbound leads, answers objections and books calls automatically.', 'The AI Sales Assistant engages every inbound lead within seconds, asks the qualifying questions your sales team would ask, and books a call directly onto your calendar for the leads worth a conversation.', ARRAY['Automatic lead qualification', 'Objection handling scripts', 'Calendar booking integration', 'CRM sync on every conversation'], ARRAY['B2B Services', 'Real Estate', 'Automation Clients'], 'Custom Quote', true, 'Published') on conflict (slug) do nothing;
insert into automation_services (name, slug, summary, description, features, industries, pricing_type, featured, status) values ('AI Booking Agent', 'ai-booking-agent', 'Handles appointment and inspection bookings without back-and-forth messages.', 'Whether it''s a property inspection, a fitting appointment or a consultation call, the AI Booking Agent finds an open slot, confirms it with the customer and syncs it to your calendar automatically.', ARRAY['Real-time calendar availability', 'Automatic reminders and reschedules', 'Two-way WhatsApp and email confirmation', 'No-show follow-up sequences'], ARRAY['Real Estate', 'Fashion Consultations', 'Clinics & Services'], 'Monthly Retainer', true, 'Published') on conflict (slug) do nothing;
insert into automation_services (name, slug, summary, description, features, industries, pricing_type, featured, status) values ('AI Knowledge Assistant', 'ai-knowledge-assistant', 'An internal assistant trained on your company''s documents, SOPs and FAQs.', 'Give your team an assistant that already knows your SOPs, pricing sheets and policies — cutting down the time spent digging through documents or waiting on a manager to reply.', ARRAY['Trained on internal documents', 'Slack, WhatsApp or web access', 'Always up to date as documents change', 'Usage and gap analytics'], ARRAY['Any growing team'], 'One-Time Build', false, 'Published') on conflict (slug) do nothing;
insert into automation_projects (title, slug, client_business, problem, solution, workflow_tools, results, project_date, featured, status) values ('24/7 Order & Support Automation for a Food Ordering Brand', 'item7go-order-automation', 'Food Ordering Company', 'Orders and customer questions were handled manually across phone and DM, causing missed orders and slow replies during peak hours.', 'Built an AI customer service and ordering agent that handles menu questions, takes full orders, and routes delivery issues to a human when needed.', ARRAY['n8n', 'LLM API', 'WhatsApp Business API', 'Google Sheets'], ARRAY['Faster response times during peak hours', 'Orders now captured automatically around the clock', 'Fewer repetitive questions reaching the support line'], '2025-10-01', true, 'Published') on conflict (slug) do nothing;
insert into automation_projects (title, slug, client_business, problem, solution, workflow_tools, results, project_date, featured, status) values ('Automated Lead Qualification & Outreach Pipeline', 'b2b-lead-qualification-workflow', 'B2B Services Company', 'The sales team was spending hours manually researching and qualifying leads before any outreach began.', 'Built an automated research and qualification workflow that scores inbound and outbound leads and routes qualified ones straight into the CRM.', ARRAY['n8n', 'CRM Integration', 'Email Automation'], ARRAY['Reduced manual research time', 'Consistent lead scoring', 'Cleaner CRM pipeline'], '2025-07-20', true, 'Published') on conflict (slug) do nothing;
